import{_ as a,o as t,c as s,l as i,t as o,N as r}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"repertoiremap | x-cmd man (man5) | map symbolic character names to Unicode code points","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | repertoiremap - map symbolic character names to Unicode code points","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"repertoiremap | x-cmd man (man5) | map symbolic character names to Unicode code points"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | repertoiremap - map symbolic character names to Unicode code points"}]]},"headers":[],"params":{"isMan":true,"man":"repertoiremap","category":"man5","desc":"map symbolic character names to Unicode code points"},"relativePath":"man5/repertoiremap.md","filePath":"man5/repertoiremap.md"}'),n={name:"man5/repertoiremap.md"},d={class:"visually-hidden"},l=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>repertoiremap - map symbolic character names to Unicode code points</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A repertoire map defines mappings between symbolic character names (mnemonics) and Unicode code points when compiling a locale with <strong>localedef</strong>(1). Using a repertoire map is optional, it is needed only when symbolic names are used instead of now preferred Unicode code points.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h3><p>The repertoiremap file starts with a header that may consist of the following keywords:</p><dl><dt><em>comment_char</em></dt><dd>is followed by a character that will be used as the comment character for the rest of the file. It defaults to the number sign (#).</dd><dt><em>escape_char</em></dt><dd>is followed by a character that should be used as the escape character for the rest of the file to mark characters that should be interpreted in a special way. It defaults to the backslash (\\).</dd></dl><p>The mapping section starts with the keyword <em>CHARIDS</em> in the first column.</p><p>The mapping lines have the following form:</p><dl><dt><em>&lt;symbolic-name&gt; &lt;code-point&gt; comment</em></dt><dd>This defines exactly one mapping, <em>comment</em> being optional.</dd></dl><p>The mapping section ends with the string <em>END CHARIDS</em>.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/usr/share/i18n/repertoiremaps</em></dt><dd>Usual default repertoire map path.</dd></dl><h2 id="standards" tabindex="-1">STANDARDS <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;STANDARDS&quot;">​</a></h2><p>POSIX.2.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Repertoire maps are deprecated in favor of Unicode code points.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>A mnemonic for the Euro sign can be defined as follows:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Eu</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">U20AC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EURO SIGN</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>locale</strong>(1), <strong>localedef</strong>(1), <strong>charmap</strong>(5), <strong>locale</strong>(5)</p>',22);function p(e,c,h,m,g,f){return t(),s("div",null,[i("h1",d,o(e.$params.man),1),l])}const k=a(n,[["render",p]]);export{b as __pageData,k as default};
